python3 - <<'EOF'
import re,os
root='AlgebraicJacobian'
def path(mod):
    return mod.replace('.','/')+'.lean'
imports={}
for dp,_,fs in os.walk(root):
    for f in fs:
        if f.endswith('.lean'):
            p=os.path.join(dp,f)
            mod=p[:-5].replace('/','.')
            txt=open(p).read()
            imports[mod]=re.findall(r'^import (AlgebraicJacobian[\w.]*)',txt,re.M)
def closure(start):
    seen=set();stack=[start]
    while stack:
        m=stack.pop()
        if m in seen: continue
        seen.add(m)
        stack+=imports.get(m,[])
    return seen
targets=['AlgebraicJacobian.Picard.Pic0ChartCoverageNoDrop','AlgebraicJacobian.Picard.Pic0ChartCoverageIndexSlack','AlgebraicJacobian.Picard.Pic0ChartAtlasCoupling','AlgebraicJacobian.Picard.Pic0ChartCoverageSlice','AlgebraicJacobian.Picard.Pic0ChartVMonotone','AlgebraicJacobian.Picard.Pic0ChartPlusFibreProducer','AlgebraicJacobian.Picard.Pic0ChartRestrictedFibre']
sorryre=re.compile(r'^[ \t]*sorry[ \t]*$|:=[ \t]*sorry',re.M)
for t in targets:
    c=closure(t)
    bad=[]
    for m in sorted(c):
        p=path(m)
        if os.path.exists(p):
            txt=open(p).read()
            n=len(sorryre.findall(txt))
            if n: bad.append((m,n))
    print(f"{t}: closure={len(c)} sorry_files={bad}")
EOF

